def get_odd_collatz(n):
    """
    Given a positive integer n, return a sorted list that has the odd numbers in collatz sequence.
    """
    odds = set()
    curr = n
    while True:
        if curr % 2 != 0:
            odds.add(curr)
        if curr == 1:
            break
        if curr % 2 == 0:
            curr //= 2
        else:
            curr = 3 * curr + 1
    return sorted(list(odds))

