import math

def closest_integer(value):
    """
    Create a function that takes a value (string) representing a number
    and returns the closest integer to it. If the number is equidistant
    from two integers, round it away from zero.
    """
    # Convert the input string to a float
    x = float(value)

    # Find the floor and ceiling of the value
    f = math.floor(x)
    c = math.ceil(x)

    # If x is already an integer, return it as an int
    if x == f:
        return int(f)

    # Calculate distances to the floor and ceiling
    d_f = x - f
    d_c = c - x

    # Compare distances to find the closest integer
    if d_f < d_c:
        return int(f)
    elif d_c < d_f:
        return int(c)
    else:
        # Tie-breaking rule: round away from zero. 
        # This means returning the integer with the larger absolute value.
        if abs(f) > abs(c):
            return int(f)
        else:
            return int(c)

