def fib4(n: int):
    if n == 0:
        return 0
    if n == 1:
        return 0
    if n == 2:
        return 2
    if n == 3:
        return 0

    # Initial values for fib4(0), fib4(1), fib4(2), fib4(3)
    a, b, c, d = 0, 0, 2, 0

    # Iteratively compute up to n
    for _ in range(4, n + 1):
        next_val = a + b + c + d
        a, b, c, d = b, c, d, next_val

    return d
